const {test}=require('node:test'),assert=require('node:assert/strict');
const {verificationProperties,deployedBaseline,rich,text,hash}=require('./record');
const m={repository:'VeamStudios/App',target:'web',commit:'a'.repeat(40)},proof={kind:'http',repository:m.repository,commit:m.commit,reportedCommit:m.commit,evidence:'https://app.test/release-info.json'};
const initial={phase:'deployed',source:'https://github.com/VeamStudios/App/actions/runs/1',releasedAt:'2026-09-11T10:00:00Z',verification:proof};
test('failed retry preserves successful production evidence and comparison baseline',()=>{const properties={'Manifest Hash':rich(hash(m)),Manifest:rich(JSON.stringify(m))};Object.assign(properties,verificationProperties({phase:'deployed',source:'https://github.com/run/2',verificationError:'Temporary endpoint failure'},initial,properties,'2026-09-11T11:00:00Z'));const o=JSON.parse(text(properties.Observation));assert.deepEqual(o.verification,proof);assert.equal(o.source,initial.source);assert.equal(o.releasedAt,initial.releasedAt);assert.equal(deployedBaseline({properties}),true);assert.equal(o.verificationError,'Temporary endpoint failure')});
test('successful retry clears only its recovered verification error and retains diagnostics',()=>{const previous={...initial,verificationError:'Temporary endpoint failure'},properties={Error:rich(previous.verificationError),'Operations Receipt':rich(JSON.stringify({notification:'already reported'}))};const recovered=verificationProperties({phase:'deployed',source:'https://github.com/run/3',verification:proof},previous,properties,'2026-09-11T12:00:00Z');assert.equal(text(recovered.Error),'');const receipt=JSON.parse(text(recovered['Operations Receipt']));assert.equal(receipt.notification,'already reported');assert.equal(receipt.resolutions[0].error,previous.verificationError);assert.equal(JSON.parse(text(recovered.Observation)).verificationError,undefined);const unrelated=verificationProperties({phase:'deployed',verification:proof},previous,{Error:rich('Uncertain Slack delivery')},'now');assert.equal(unrelated.Error,undefined)});
test('a first failed verification cannot manufacture a successful observation',()=>{const properties={Manifest:rich(JSON.stringify(m)),'Manifest Hash':rich(hash(m)),...verificationProperties({phase:'deployed',verificationError:'unavailable',source:'https://github.com/run/1'},null,{},'2026-09-11T12:00:00Z')};assert.equal(deployedBaseline({properties}),false)});
